box-shadow:0 12px 26px rgba(11,33,84,.12);transform:translateY(-3px);}\r\n.mt-links a.is-current{border-left:4px solid var(--mt-red);background:var(--mt-bg);}\r\n.mt-mini-rows{margin-top:18px;}\r\n.mt-mini-rows span{display:block;padding:12px 0;border-bottom:1px solid rgba(255,255,255,.14);}\r\n.mt-mini-rows span:last-child{border-bottom:none;padding-bottom:0;}\r\n.mt-mini-rows i{color:var(--mt-gold);width:24px;text-align:center;margin-right:8px;}\r\n.mt-mini-rows b{display:block;color:var(--mt-cream);font-family:Barlow,sans-serif;font-size:11.5px;letter-spacing:1.6px;text-transform:uppercase;margin-bottom:5px;}\r\n.mt-btn-inline{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px;}\r\n.mt-btn{display:inline-block;background:var(--mt-green);color:#FFFFFF!important;font-family:Barlow,sans-serif;font-weight:700;font-size:15px;padding:13px 26px;border-radius:8px;text-decoration:none;transition:transform .25s ease,box-shadow .25s ease;}\r\n.mt-btn-red{background:var(--mt-red);}\r\n.mt-btn:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(0,0,0,.25);color:#FFFFFF!important;text-decoration:none;}\r\n@media(max-width:921px){.mt-cards,.mt-cards.c3{grid-template-columns:repeat(2,1fr);}.mt-links{grid-template-columns:repeat(2,1fr);}}\r\n@media(max-width:600px){.mt-cards,.mt-cards.c3,.mt-cards.c2{grid-template-columns:1fr;}.mt-links{grid-template-columns:1fr;}.mt-btn-inline{flex-direction:column;}.mt-btn{width:100%;text-align:center;}}\r\n\r\n/* MT FASE 3b: ritme spacing + chips + kartu est */\r\n.mt-lead,.mt-lead-dark{margin-bottom:0;}\r\n.mt-checks{margin-top:6px;}\r\n.mt-mini-rows{margin-top:0;}\r\n.mt-est{align-self:flex-start;}\r\n.mt-chips span{position:relative;padding-left:34px;border-left:0;}\r\n.mt-chips span::before{content:\"\";position:absolute;left:16px;top:50%;width:7px;height:7px;border-radius:50%;background:var(--mt-red);transform:translateY(-50%);}\r\n\r\n/* MT FASE 3c: gutter tablet/mobile */\r\n@media(max-width:1024px){\r\n.page-id-31 .elementor-